/**
 * 去重并保持首次出现顺序。
 * 字符串按大小写不敏感去重，保留第一次出现的写法。
 */
export function unique(items) {
  const seen = new Set()
  const out = []
  for (const item of items) {
    const key = String(item).toLowerCase()
    if (seen.has(key)) continue
    seen.add(key)
    out.push(item)
  }
  return out
}
